rules::WFP Headcount.rules:
SKIPCHECK;

# WFP Headcount dims: Period, Version, Entity, Cost Centre, Position, Measure
['_End Idx'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'End Period') @= '', 999,
      ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'End Period'), 'Period Index') );

['_Active'] = N:
  IF( !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
      & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre')
      & ATTRN('WFP Period', !WFP Period, 'Period Index')
          >= ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index')
      & ATTRN('WFP Period', !WFP Period, 'Period Index') <= ['_End Idx'],
      1, 0 );

['Headcount'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled', 1, 0 );

['FTE'] = N:
  ['_Active'] * ATTRN('WFP Position', !WFP Position, 'FTE');

['Open Positions'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Open Req', 1, 0 );

FEEDERS;

['Headcount'] => ['FTE'], ['Open Positions'];

process::WFP Seed Dimension Attributes.PrologProcedure:
#Region WFP Seed Dimension Attributes
# Sets the attribute VALUES that were originally built declaratively and so do not
# survive a deploy: WFP Period (index/days/prior/FY), WFP Job Family (Pay Index),
# WFP Entity, WFP Version, WFP Cost Centre. Idempotent — safe to re-run.

# --- WFP Period: Period Index (chronological), Days In Month, Prior Period, FY ---
cPer   = 'WFP Period';
nCount = DIMSIZ( cPer );
nIdx   = 0;
vPrev  = '';
nE = 1;
WHILE( nE <= nCount );
   vPer = DIMNM( cPer, nE );
   # leaf months are numeric elements named YYYY-MM
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = nIdx + 1;
      nMon = NUMBR( SUBST( vPer, 6, 2 ) );
      nDays = 31;
      IF( nMon = 2 );
         nDays = 28;
      ENDIF;
      IF( nMon = 4 % nMon = 6 % nMon = 9 % nMon = 11 );
         nDays = 30;
      ENDIF;
      AttrPutN( nIdx,  cPer, vPer, 'Period Index' );
      AttrPutN( nDays, cPer, vPer, 'Days In Month' );
      AttrPutS( vPrev, cPer, vPer, 'Prior Period' );
      AttrPutS( 'FY' | SUBST( vPer, 1, 4 ), cPer, vPer, 'FY' );
      vPrev = vPer;
   ENDIF;
   nE = nE + 1;
END;

# --- WFP Job Family: Pay Index ---
vJF = 'Engineering;1.1~Product;1.08~Sales;1.05~Marketing;1~Customer Success;0.98~Finance;1~People;0.98~IT;1~Admin;0.92~Leadership;1.15~';
WHILE( SCAN( '~', vJF ) > 1 );
   nS = SCAN( '~', vJF ); vRec = SUBST( vJF, 1, nS - 1 ) | ';'; vJF = SUBST( vJF, nS + 1, LONG( vJF ) - nS );
   nS = SCAN( ';', vRec ); vFam = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPi  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Job Family', vFam ) > 0 );
      AttrPutN( nPi, 'WFP Job Family', vFam, 'Pay Index' );
   ENDIF;
END;

# --- WFP Entity: Local Currency, Primary Location, Reporting Currency ---
vEn = 'Group;;;GBP~UK Ltd;GBP;London;GBP~US Inc;USD;New York;GBP~NZ Ltd;NZD;Auckland;GBP~';
WHILE( SCAN( '~', vEn ) > 1 );
   nS = SCAN( '~', vEn ); vRec = SUBST( vEn, 1, nS - 1 ) | ';'; vEn = SUBST( vEn, nS + 1, LONG( vEn ) - nS );
   nS = SCAN( ';', vRec ); vEnt = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vLC  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPL  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vRC  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Entity', vEnt ) > 0 );
      IF( vLC @<> '' );
         AttrPutS( vLC, 'WFP Entity', vEnt, 'Local Currency' );
      ENDIF;
      IF( vPL @<> '' );
         AttrPutS( vPL, 'WFP Entity', vEnt, 'Primary Location' );
      ENDIF;
      AttrPutS( vRC, 'WFP Entity', vEnt, 'Reporting Currency' );
   ENDIF;
END;

# --- WFP Version: Version Type (Calculated | Frozen), Description ---
# Phase 3.5: Working removed. Actual/Budget/Forecast/Downside are all Calculated
# for now; Actual becomes Frozen at the Phase 7 payroll load. Snapshot members
# (FCST YYYY-MM, Budget FINAL) are set to Frozen by WFP Snapshot Version.
vVr = 'Actual;Calculated;Modelled actual — becomes Frozen at the Phase 7 payroll load~Budget;Calculated;Approved plan being built — snapshot to Budget FINAL at lock~Forecast;Calculated;Working current model — closed months = Actual, open months own assumptions~Downside;Calculated;Self-contained downside (cost-pressure) scenario~';
WHILE( SCAN( '~', vVr ) > 1 );
   nS = SCAN( '~', vVr ); vRec = SUBST( vVr, 1, nS - 1 ) | ';'; vVr = SUBST( vVr, nS + 1, LONG( vVr ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vTyp = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vDsc = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Version', vVer ) > 0 );
      AttrPutS( vTyp, 'WFP Version', vVer, 'Version Type' );
      AttrPutS( vDsc, 'WFP Version', vVer, 'Description' );
   ENDIF;
END;

# --- WFP Cost Centre: Function, CC Name ---
vCC = 'CC-ENG-PLT;R&D;Engineering - Platform~CC-ENG-APP;R&D;Engineering - Application~CC-PROD;R&D;Product Management~CC-SALES;S&M;Sales~CC-SALESOPS;S&M;Sales Operations~CC-MKT;S&M;Marketing~CC-CS;S&M;Customer Success~CC-FIN;G&A;Finance~CC-PPL;G&A;People & HR~CC-ITOPS;G&A;IT & Operations~CC-EXEC;G&A;Executive~';
WHILE( SCAN( '~', vCC ) > 1 );
   nS = SCAN( '~', vCC ); vRec = SUBST( vCC, 1, nS - 1 ) | ';'; vCC = SUBST( vCC, nS + 1, LONG( vCC ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vFun = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vNam = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutS( vFun, 'WFP Cost Centre', vCtr, 'Function' );
      AttrPutS( vNam, 'WFP Cost Centre', vCtr, 'CC Name' );
   ENDIF;
END;

process::WFP Snapshot Version.PrologProcedure:
#Region WFP Snapshot Version — freeze a calculating version into a Frozen member
# Phase 3.5. Copies the INPUT layer (Workforce Input, Assumptions, FX Rates, Pay
# Rates) of pSource into pTarget; Workforce Cost + Headcount then calculate for
# pTarget to exactly the pSource picture and stay there while the inputs are
# untouched. pTarget is created if absent and marked Version Type = Frozen.
# Run at month-end close (pSource = Forecast) or budget lock (pSource = Budget).
cVer = 'WFP Version';

nStop = 0;
IF( DIMIX( cVer, pSource ) = 0 );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Source version not found: ' | pSource );
   nStop = 1;
ENDIF;
IF( nStop = 0 & ATTRS( cVer, pSource, 'Version Type' ) @<> 'Calculated' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Refused: source "' | pSource | '" is not a Calculated version.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & TRIM( pTarget ) @= '' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target member name is blank.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & pTarget @= pSource );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target equals source.' );
   nStop = 1;
ENDIF;

IF( nStop = 0 );
   # create the target member if needed (Direct = committed immediately), mark Frozen
   IF( DIMIX( cVer, pTarget ) = 0 );
      DimensionElementInsertDirect( cVer, '', pTarget, 'N' );
   ENDIF;
   AttrPutS( 'Frozen', cVer, pTarget, 'Version Type' );
   AttrPutS( 'Snapshot of ' | pSource | ' — ' | TIMST( NOW, '\Y-\m-\d' ), cVer, pTarget, 'Description' );

   nCopied = 0;

   # --- WFP Workforce Input : Period x Position x Measure ---
   cWI = 'WFP Workforce Input';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Workforce Input Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vPos = DIMNM( 'WFP Position', nJ );
            IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Workforce Input Measure', nK );
                  IF( DTYPE( 'WFP Workforce Input Measure', vM ) @= 'N' );
                     nVal = CellGetN( cWI, vP, pSource, vPos, vM );
                     IF( nVal <> 0 );
                        CellPutN( nVal, cWI, vP, pTarget, vPos, vM );
                        nCopied = nCopied + 1;
                     ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Assumptions : Period x Entity x Measure ---
   cAS = 'WFP Assumptions';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Entity' ); nC = DIMSIZ( 'WFP Assumptions Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vEnt = DIMNM( 'WFP Entity', nJ );
            IF( DTYPE( 'WFP Entity', vEnt ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Assumptions Measure', nK );
                  IF( DTYPE( 'WFP Assumptions Measure', vM ) @= 'N' );
                     nVal = CellGetN( cAS, vP, pSource, vEnt, vM );
                     IF( nVal <> 0 );
                        CellPutN( nVal, cAS, vP, pTarget, vEnt, vM );
                        nCopied = nCopied + 1;
                     ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP FX Rates : Period x Currency x FX Rate Type x Measure ---
   cFX = 'WFP FX Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Currency' ); nC = DIMSIZ( 'WFP FX Rate Type' ); nD = DIMSIZ( 'WFP FX Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vCur = DIMNM( 'WFP Currency', nJ );
            IF( DTYPE( 'WFP Currency', vCur ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vRt = DIMNM( 'WFP FX Rate Type', nK );
                  IF( DTYPE( 'WFP FX Rate Type', vRt ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vM = DIMNM( 'WFP FX Rates Measure', nL );
                        IF( DTYPE( 'WFP FX Rates Measure', vM ) @= 'N' );
                           nVal = CellGetN( cFX, vP, pSource, vCur, vRt, vM );
                           IF( nVal <> 0 );
                              CellPutN( nVal, cFX, vP, pTarget, vCur, vRt, vM );
                              nCopied = nCopied + 1;
                           ENDIF;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Pay Rates : Period x Grade x Job Family x Location x Measure ---
   cPR = 'WFP Pay Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Grade' ); nC = DIMSIZ( 'WFP Job Family' ); nD = DIMSIZ( 'WFP Location' ); nE = DIMSIZ( 'WFP Pay Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vG = DIMNM( 'WFP Grade', nJ );
            IF( DTYPE( 'WFP Grade', vG ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vJF = DIMNM( 'WFP Job Family', nK );
                  IF( DTYPE( 'WFP Job Family', vJF ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vLoc = DIMNM( 'WFP Location', nL );
                        IF( DTYPE( 'WFP Location', vLoc ) @= 'N' );
                           nMx = 1;
                           WHILE( nMx <= nE );
                              vM = DIMNM( 'WFP Pay Rates Measure', nMx );
                              IF( DTYPE( 'WFP Pay Rates Measure', vM ) @= 'N' );
                                 nVal = CellGetN( cPR, vP, pSource, vG, vJF, vLoc, vM );
                                 IF( nVal <> 0 );
                                    CellPutN( nVal, cPR, vP, pTarget, vG, vJF, vLoc, vM );
                                    nCopied = nCopied + 1;
                                 ENDIF;
                              ENDIF;
                              nMx = nMx + 1;
                           END;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   ASCIIOUTPUT( 'WFP_Snapshot_ok.txt', 'Snapshot ' | pSource | ' -> ' | pTarget | ' : ' | NUMBERTOSTRING( nCopied ) | ' input cells copied. Cost + Headcount recalculate for ' | pTarget | '.' );
ENDIF;

rules::WFP Workforce Cost.rules:
SKIPCHECK;

# Non-Calculating versions (Actual + snapshots) hold stored data — skip all calc.
[] = N: IF(ELPAR('WFP Version', !WFP Version, 1) @= 'Non-Calculating', STET, CONTINUE);

# ===== Reporting-currency translation =====
# WFP Workforce Cost dims: Period, Version, Entity, Cost Centre, Pay Component, Currency, Position, Measure
['Reporting'] = N:
    DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Pay Component, 'GBP', !WFP Position, 'Amount') * DB('WFP FX Rates', !WFP Period, !WFP Version, 'GBP', 'Average', 'Rate')
  + DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Pay Component, 'USD', !WFP Position, 'Amount') * DB('WFP FX Rates', !WFP Period, !WFP Version, 'USD', 'Average', 'Rate')
  + DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Pay Component, 'NZD', !WFP Position, 'Amount') * DB('WFP FX Rates', !WFP Period, !WFP Version, 'NZD', 'Average', 'Rate');

# ===== Helpers =====
['_Start Index'] = N: ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index');

['_End Index'] = N: IF(ATTRS('WFP Position', !WFP Position, 'End Period') @= '', 999, ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'End Period'), 'Period Index'));

['_In Window'] = N: IF(ATTRN('WFP Period', !WFP Period, 'Period Index') >= ['_Start Index'] & ATTRN('WFP Period', !WFP Period, 'Period Index') <= ['_End Index'], 1, 0);

['_Start Frac'] = N:
  IF(ATTRN('WFP Period', !WFP Period, 'Period Index') = ['_Start Index'],
     (ATTRN('WFP Period', !WFP Period, 'Days In Month') - ATTRN('WFP Position', !WFP Position, 'Start Day') + 1) / ATTRN('WFP Period', !WFP Period, 'Days In Month'), 1);

['_End Frac'] = N:
  IF(ATTRS('WFP Position', !WFP Position, 'End Period') @<> '' & ATTRN('WFP Period', !WFP Period, 'Period Index') = ['_End Index'],
     ATTRN('WFP Position', !WFP Position, 'End Day') / ATTRN('WFP Period', !WFP Period, 'Days In Month'), 1);

['_Active Fraction'] = N: ['_In Window'] * ['_Start Frac'] * ['_End Frac'];

['_Annual Salary'] = N:
  IF(ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled' & DB('WFP Workforce Input', !WFP Period, !WFP Version, !WFP Position, 'Base Salary') > 0,
     DB('WFP Workforce Input', !WFP Period, !WFP Version, !WFP Position, 'Base Salary'),
     DB('WFP Pay Rates', !WFP Period, !WFP Version, ATTRS('WFP Position', !WFP Position, 'Grade'), ATTRS('WFP Position', !WFP Position, 'Job Family'), ATTRS('WFP Position', !WFP Position, 'Location'), 'Salary Mid'));

['_Monthly Base Full'] = N:
  IF(!WFP Currency @= ATTRS('WFP Position', !WFP Position, 'Salary Currency') & !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity') & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre'),
     ['_Annual Salary'] / 12 * DB('WFP Workforce Input', !WFP Period, !WFP Version, !WFP Position, 'FTE'), 0);

['_Earnings YTD'] = N:
  ['Base']
  + IF(SUBST(!WFP Period, 6, 2) @= '01', 0, DB('WFP Workforce Cost', ATTRS('WFP Period', !WFP Period, 'Prior Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, '_Earnings YTD', !WFP Currency, !WFP Position, 'Amount'));

['_Employer Tax YTD'] = N:
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 1', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 1', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 1', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 2', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 2', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 2', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 3', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 3', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 3', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 4', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 4', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 4', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 5', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 5', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 5', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 6', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 6', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 6', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 7', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 7', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employer Payroll Tax', 'Band 7', 'Rate');

['_Prior Employer Tax YTD'] = N: IF(SUBST(!WFP Period, 6, 2) @= '01', 0, DB('WFP Workforce Cost', ATTRS('WFP Period', !WFP Period, 'Prior Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, '_Employer Tax YTD', !WFP Currency, !WFP Position, 'Amount'));

['_Employee Tax YTD'] = N:
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 1', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 1', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 1', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 2', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 2', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 2', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 3', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 3', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 3', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 4', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 4', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 4', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 5', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 5', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 5', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 6', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 6', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 6', 'Rate')
  +
  MAX(0, MIN(['_Earnings YTD'], DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 7', 'Threshold To')) - DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 7', 'Threshold From')) * DB('WFP Tax Bands', ATTRS('WFP Position', !WFP Position, 'Tax Jurisdiction'), 'Employee Income Tax', 'Band 7', 'Rate');

['_Prior Employee Tax YTD'] = N: IF(SUBST(!WFP Period, 6, 2) @= '01', 0, DB('WFP Workforce Cost', ATTRS('WFP Period', !WFP Period, 'Prior Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, '_Employee Tax YTD', !WFP Currency, !WFP Position, 'Amount'));

# ===== Components (local currency) =====
['Base'] = N: ['_Monthly Base Full'] * ['_Active Fraction'];

['Gross Pay'] = N: ['Base'];

['Employer Payroll Tax'] = N: IF(ATTRS('WFP Position', !WFP Position, 'Employment Type') @= 'Contractor', 0, ['_Employer Tax YTD'] - ['_Prior Employer Tax YTD']);

['Employer Pension'] = N: IF(ATTRS('WFP Position', !WFP Position, 'Employment Type') @= 'Contractor', 0, ['Base'] * DB('WFP Pay Rates', !WFP Period, !WFP Version, ATTRS('WFP Position', !WFP Position, 'Grade'), ATTRS('WFP Position', !WFP Position, 'Job Family'), ATTRS('WFP Position', !WFP Position, 'Location'), 'Pension Pct'));

['Employee Income Tax'] = N: IF(ATTRS('WFP Position', !WFP Position, 'Employment Type') @= 'Contractor', 0, ['_Employee Tax YTD'] - ['_Prior Employee Tax YTD']);

['Employee Pension'] = N: IF(ATTRS('WFP Position', !WFP Position, 'Employment Type') @= 'Contractor', 0, ['Base'] * DB('WFP Pay Rates', !WFP Period, !WFP Version, ATTRS('WFP Position', !WFP Position, 'Grade'), ATTRS('WFP Position', !WFP Position, 'Job Family'), ATTRS('WFP Position', !WFP Position, 'Location'), 'Employee Pension Pct'));

['Benefits'] = N:
  IF(['_Monthly Base Full'] = 0, 0,
  IF(ATTRS('WFP Position', !WFP Position, 'Employment Type') @= 'Contractor', 0,
     DB('WFP Pay Rates', !WFP Period, !WFP Version, ATTRS('WFP Position', !WFP Position, 'Grade'), ATTRS('WFP Position', !WFP Position, 'Job Family'), ATTRS('WFP Position', !WFP Position, 'Location'), 'Benefits Annual') / 12 * DB('WFP Workforce Input', !WFP Period, !WFP Version, !WFP Position, 'FTE') * ['_Active Fraction']));

['Bonus'] = N:
  IF(ATTRS('WFP Position', !WFP Position, 'Employment Type') @= 'Contractor', 0,
     ['Base'] * DB('WFP Assumptions', !WFP Period, !WFP Version, !WFP Entity, 'Bonus Pool %'));

['One-Time'] = N:
  IF(!WFP Currency @= ATTRS('WFP Position', !WFP Position, 'Salary Currency')
     & !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
     & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre'),
     DB('WFP Workforce Input', !WFP Period, !WFP Version, !WFP Position, 'One-Time Amount'), 0);

['Net Pay'] = N: ['Gross Pay'] - ['Employee Deductions'];

FEEDERS;

['_Monthly Base Full'] => ['Base'], ['Gross Pay'], ['Employer Payroll Tax'], ['Employer Pension'], ['Benefits'], ['Bonus'], ['One-Time'],
  ['Employee Income Tax'], ['Employee Pension'], ['Net Pay'],
  ['_Earnings YTD'], ['_Employer Tax YTD'], ['_Prior Employer Tax YTD'], ['_Employee Tax YTD'], ['_Prior Employee Tax YTD'];

['_Monthly Base Full'] =>
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Base', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Gross Pay', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Employer Payroll Tax', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Employer Pension', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Benefits', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Bonus', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'One-Time', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Employee Income Tax', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Employee Pension', 'Reporting', !WFP Position, 'Amount'),
  DB('WFP Workforce Cost', !WFP Period, !WFP Version, !WFP Entity, !WFP Cost Centre, 'Net Pay', 'Reporting', !WFP Position, 'Amount');

rules::WFP Headcount.rules:
SKIPCHECK;

# WFP Headcount dims: Period, Version, Entity, Cost Centre, Position, Measure

[] = N: IF(ELPAR('WFP Version', !WFP Version, 1) @= 'Non-Calculating', STET, CONTINUE);

['_End Idx'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'End Period') @= '', 999,
      ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'End Period'), 'Period Index') );

['_Active'] = N:
  IF( !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
      & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre')
      & ATTRN('WFP Period', !WFP Period, 'Period Index')
          >= ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index')
      & ATTRN('WFP Period', !WFP Period, 'Period Index') <= ['_End Idx'],
      1, 0 );

['Headcount'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled', 1, 0 );

['FTE'] = N:
  ['_Active'] * ATTRN('WFP Position', !WFP Position, 'FTE');

['Open Positions'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Open Req', 1, 0 );

FEEDERS;

['Headcount'] => ['FTE'], ['Open Positions'];

process::WFP Seed Dimension Attributes.PrologProcedure:
#Region WFP Seed Dimension Attributes
# Sets the attribute VALUES that were originally built declaratively and so do not
# survive a deploy: WFP Period (index/days/prior/FY), WFP Job Family (Pay Index),
# WFP Entity, WFP Version, WFP Cost Centre. Idempotent — safe to re-run.

# --- WFP Period: Period Index (chronological), Days In Month, Prior Period, FY ---
cPer   = 'WFP Period';
nCount = DIMSIZ( cPer );
nIdx   = 0;
vPrev  = '';
nE = 1;
WHILE( nE <= nCount );
   vPer = DIMNM( cPer, nE );
   # leaf months are numeric elements named YYYY-MM
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = nIdx + 1;
      nMon = NUMBR( SUBST( vPer, 6, 2 ) );
      nDays = 31;
      IF( nMon = 2 );
         nDays = 28;
      ENDIF;
      IF( nMon = 4 % nMon = 6 % nMon = 9 % nMon = 11 );
         nDays = 30;
      ENDIF;
      AttrPutN( nIdx,  cPer, vPer, 'Period Index' );
      AttrPutN( nDays, cPer, vPer, 'Days In Month' );
      AttrPutS( vPrev, cPer, vPer, 'Prior Period' );
      AttrPutS( 'FY' | SUBST( vPer, 1, 4 ), cPer, vPer, 'FY' );
      vPrev = vPer;
   ENDIF;
   nE = nE + 1;
END;

# --- WFP Job Family: Pay Index ---
vJF = 'Engineering;1.1~Product;1.08~Sales;1.05~Marketing;1~Customer Success;0.98~Finance;1~People;0.98~IT;1~Admin;0.92~Leadership;1.15~';
WHILE( SCAN( '~', vJF ) > 1 );
   nS = SCAN( '~', vJF ); vRec = SUBST( vJF, 1, nS - 1 ) | ';'; vJF = SUBST( vJF, nS + 1, LONG( vJF ) - nS );
   nS = SCAN( ';', vRec ); vFam = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPi  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Job Family', vFam ) > 0 );
      AttrPutN( nPi, 'WFP Job Family', vFam, 'Pay Index' );
   ENDIF;
END;

# --- WFP Entity: Local Currency, Primary Location, Reporting Currency ---
vEn = 'Group;;;GBP~UK Ltd;GBP;London;GBP~US Inc;USD;New York;GBP~NZ Ltd;NZD;Auckland;GBP~';
WHILE( SCAN( '~', vEn ) > 1 );
   nS = SCAN( '~', vEn ); vRec = SUBST( vEn, 1, nS - 1 ) | ';'; vEn = SUBST( vEn, nS + 1, LONG( vEn ) - nS );
   nS = SCAN( ';', vRec ); vEnt = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vLC  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPL  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vRC  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Entity', vEnt ) > 0 );
      IF( vLC @<> '' );
         AttrPutS( vLC, 'WFP Entity', vEnt, 'Local Currency' );
      ENDIF;
      IF( vPL @<> '' );
         AttrPutS( vPL, 'WFP Entity', vEnt, 'Primary Location' );
      ENDIF;
      AttrPutS( vRC, 'WFP Entity', vEnt, 'Reporting Currency' );
   ENDIF;
END;

# --- WFP Version: Version Type (Calculated | Static), Description ---
# Budget / Forecast / Downside are Calculated (roll up to Calculating).
# Actual is Static — non-calculating, populated by the payroll load (Phase 7);
# it rolls up to Non-Calculating and the [] STET/CONTINUE guard in the cube rules
# stops all calc for it. Snapshot members are set to Static by WFP Snapshot Version.
vVr = 'Actual;Static;Actuals — non-calculating; populated by the payroll load (Phase 7)~Budget;Calculated;Approved plan being built~Forecast;Calculated;Working current model — closed months = Actual, open months own assumptions~Downside;Calculated;Self-contained downside (cost-pressure) scenario~';
WHILE( SCAN( '~', vVr ) > 1 );
   nS = SCAN( '~', vVr ); vRec = SUBST( vVr, 1, nS - 1 ) | ';'; vVr = SUBST( vVr, nS + 1, LONG( vVr ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vTyp = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vDsc = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Version', vVer ) > 0 );
      AttrPutS( vTyp, 'WFP Version', vVer, 'Version Type' );
      AttrPutS( vDsc, 'WFP Version', vVer, 'Description' );
   ENDIF;
END;

# --- WFP Cost Centre: Function, CC Name ---
vCC = 'CC-ENG-PLT;R&D;Engineering - Platform~CC-ENG-APP;R&D;Engineering - Application~CC-PROD;R&D;Product Management~CC-SALES;S&M;Sales~CC-SALESOPS;S&M;Sales Operations~CC-MKT;S&M;Marketing~CC-CS;S&M;Customer Success~CC-FIN;G&A;Finance~CC-PPL;G&A;People & HR~CC-ITOPS;G&A;IT & Operations~CC-EXEC;G&A;Executive~';
WHILE( SCAN( '~', vCC ) > 1 );
   nS = SCAN( '~', vCC ); vRec = SUBST( vCC, 1, nS - 1 ) | ';'; vCC = SUBST( vCC, nS + 1, LONG( vCC ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vFun = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vNam = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutS( vFun, 'WFP Cost Centre', vCtr, 'Function' );
      AttrPutS( vNam, 'WFP Cost Centre', vCtr, 'CC Name' );
   ENDIF;
END;

process::WFP Snapshot Version.PrologProcedure:
#Region WFP Snapshot Version — copy a calculating version into a static member
# Copies pSource -> pTarget: the input cubes (Workforce Input, Assumptions, FX
# Rates, Pay Rates) AND the calculated output (Workforce Cost, Headcount).
# pTarget is created if absent, parented under Non-Calculating, and marked
# Version Type = Static, so the [] STET/CONTINUE guard in the cube rules stops
# all calc for it — it holds exactly the pSource picture at snapshot time.
# Run at month-end close (pSource = Forecast) or budget lock (pSource = Budget).
cVer = 'WFP Version';

nStop = 0;
IF( DIMIX( cVer, pSource ) = 0 );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Source version not found: ' | pSource );
   nStop = 1;
ENDIF;
IF( nStop = 0 & ATTRS( cVer, pSource, 'Version Type' ) @<> 'Calculated' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Refused: source "' | pSource | '" is not a Calculated version.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & TRIM( pTarget ) @= '' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target member name is blank.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & pTarget @= pSource );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target equals source.' );
   nStop = 1;
ENDIF;

IF( nStop = 0 );
   IF( DIMIX( cVer, pTarget ) = 0 );
      DimensionElementInsertDirect( cVer, '', pTarget, 'N' );
   ENDIF;
   AttrPutS( 'Static', cVer, pTarget, 'Version Type' );
   AttrPutS( 'Snapshot of ' | pSource | ' - ' | TIMST( NOW, '\Y-\m-\d' ), cVer, pTarget, 'Description' );
   IF( ELISANC( cVer, 'Non-Calculating', pTarget ) = 0 );
      DimensionElementComponentAdd( cVer, 'Non-Calculating', pTarget, 1 );
   ENDIF;

   nCopied = 0;

   # --- WFP Workforce Input : Period x Position x Measure ---
   cWI = 'WFP Workforce Input';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Workforce Input Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vPos = DIMNM( 'WFP Position', nJ );
            IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Workforce Input Measure', nK );
                  IF( DTYPE( 'WFP Workforce Input Measure', vM ) @= 'N' );
                     nVal = CellGetN( cWI, vP, pSource, vPos, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cWI, vP, pTarget, vPos, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Assumptions : Period x Entity x Measure ---
   cAS = 'WFP Assumptions';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Entity' ); nC = DIMSIZ( 'WFP Assumptions Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vEnt = DIMNM( 'WFP Entity', nJ );
            IF( DTYPE( 'WFP Entity', vEnt ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Assumptions Measure', nK );
                  IF( DTYPE( 'WFP Assumptions Measure', vM ) @= 'N' );
                     nVal = CellGetN( cAS, vP, pSource, vEnt, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cAS, vP, pTarget, vEnt, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP FX Rates : Period x Currency x FX Rate Type x Measure ---
   cFX = 'WFP FX Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Currency' ); nC = DIMSIZ( 'WFP FX Rate Type' ); nD = DIMSIZ( 'WFP FX Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vCur = DIMNM( 'WFP Currency', nJ );
            IF( DTYPE( 'WFP Currency', vCur ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vRt = DIMNM( 'WFP FX Rate Type', nK );
                  IF( DTYPE( 'WFP FX Rate Type', vRt ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vM = DIMNM( 'WFP FX Rates Measure', nL );
                        IF( DTYPE( 'WFP FX Rates Measure', vM ) @= 'N' );
                           nVal = CellGetN( cFX, vP, pSource, vCur, vRt, vM );
                           IF( nVal <> 0 ); CellPutN( nVal, cFX, vP, pTarget, vCur, vRt, vM ); nCopied = nCopied + 1; ENDIF;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Pay Rates : Period x Grade x Job Family x Location x Measure ---
   cPR = 'WFP Pay Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Grade' ); nC = DIMSIZ( 'WFP Job Family' ); nD = DIMSIZ( 'WFP Location' ); nE = DIMSIZ( 'WFP Pay Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vG = DIMNM( 'WFP Grade', nJ );
            IF( DTYPE( 'WFP Grade', vG ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vJF = DIMNM( 'WFP Job Family', nK );
                  IF( DTYPE( 'WFP Job Family', vJF ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vLoc = DIMNM( 'WFP Location', nL );
                        IF( DTYPE( 'WFP Location', vLoc ) @= 'N' );
                           nMx = 1;
                           WHILE( nMx <= nE );
                              vM = DIMNM( 'WFP Pay Rates Measure', nMx );
                              IF( DTYPE( 'WFP Pay Rates Measure', vM ) @= 'N' );
                                 nVal = CellGetN( cPR, vP, pSource, vG, vJF, vLoc, vM );
                                 IF( nVal <> 0 ); CellPutN( nVal, cPR, vP, pTarget, vG, vJF, vLoc, vM ); nCopied = nCopied + 1; ENDIF;
                              ENDIF;
                              nMx = nMx + 1;
                           END;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Workforce Cost + WFP Headcount OUTPUT : per position, at its own
   #     Home Entity / Cost Centre, for its Salary Currency + Reporting ---
   cWC = 'WFP Workforce Cost'; cHC = 'WFP Headcount';
   vPCs = 'Base|Employer Payroll Tax|Employer Pension|Benefits|Bonus|One-Time|Gross Pay|Employee Income Tax|Employee Pension|Net Pay|';
   vHMs = 'Headcount|FTE|Open Positions|';
   nB = DIMSIZ( 'WFP Position' ); nA = DIMSIZ( 'WFP Period' );
   nJ = 1;
   WHILE( nJ <= nB );
      vPos = DIMNM( 'WFP Position', nJ );
      IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
         vEnt = ATTRS( 'WFP Position', vPos, 'Home Entity' );
         vCC  = ATTRS( 'WFP Position', vPos, 'Cost Centre' );
         vSC  = ATTRS( 'WFP Position', vPos, 'Salary Currency' );
         nI = 1;
         WHILE( nI <= nA );
            vP = DIMNM( 'WFP Period', nI );
            IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
               vL = vPCs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vPC = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  nVal = CellGetN( cWC, vP, pSource, vEnt, vCC, vPC, vSC, vPos, 'Amount' );
                  IF( nVal <> 0 ); CellPutN( nVal, cWC, vP, pTarget, vEnt, vCC, vPC, vSC, vPos, 'Amount' ); nCopied = nCopied + 1; ENDIF;
                  nVal = CellGetN( cWC, vP, pSource, vEnt, vCC, vPC, 'Reporting', vPos, 'Amount' );
                  IF( nVal <> 0 ); CellPutN( nVal, cWC, vP, pTarget, vEnt, vCC, vPC, 'Reporting', vPos, 'Amount' ); nCopied = nCopied + 1; ENDIF;
               END;
               vL = vHMs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vHM = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  nVal = CellGetN( cHC, vP, pSource, vEnt, vCC, vPos, vHM );
                  IF( nVal <> 0 ); CellPutN( nVal, cHC, vP, pTarget, vEnt, vCC, vPos, vHM ); nCopied = nCopied + 1; ENDIF;
               END;
            ENDIF;
            nI = nI + 1;
         END;
      ENDIF;
      nJ = nJ + 1;
   END;

   ASCIIOUTPUT( 'WFP_Snapshot_ok.txt', 'Snapshot ' | pSource | ' -> ' | pTarget | ' : ' | NUMBERTOSTRING( nCopied ) | ' cells copied (input + output). ' | pTarget | ' is Static under Non-Calculating.' );
